SELECT inquiry_id, u_id, inquiry_type, title, content, inquiry_status, created_at, updated_at
FROM inquiry
WHERE inquiry_id = #{inquiryId} AND u_id = #{uId}

SELECT answer_id, inquiry_id, admin_id, answer_content, created_at, updated_at
FROM inquiry_answer
WHERE inquiry_id = #{inquiryId}
